import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import './WhitespaceConverter.css';

const WhitespaceConverter = () => {
  const [input, setInput] = useState('');
  const [output, setOutput] = useState('');
  const [mode, setMode] = useState('show'); // 'show' or 'hide'

  const showWhitespace = () => {
    const converted = input
      .replace(/ /g, '·')
      .replace(/\t/g, '→   ')
      .replace(/\n/g, '↵\n');
    setOutput(converted);
    setMode('show');

    // Scroll to top to show results
    setTimeout(() => {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }, 100);
  };

  const hideWhitespace = () => {
    const converted = input
      .replace(/·/g, ' ')
      .replace(/→   /g, '\t')
      .replace(/↵\n/g, '\n')
      .replace(/↵/g, '');
    setOutput(converted);
    setMode('hide');

    // Scroll to top to show results
    setTimeout(() => {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }, 100);
  };

  const clearAll = () => {
    setInput('');
    setOutput('');
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(output);
  };

  const useOutput = () => {
    setInput(output);
    setOutput('');
  };

  return (
    <div className="whitespace-converter-page">
      <div className="whitespace-header">
        <Link to="/" className="back-button">← Back to Home</Link>
        <h1>Whitespace Converter</h1>
        <p>Convert whitespace to visible characters and back</p>
      </div>

      <div className="whitespace-container">
        {output && (
          <div className="output-section">
            <div className="output-header">
              <h2>Result</h2>
              <div className="output-buttons">
                <button onClick={useOutput} className="use-button">
                  Use as Input
                </button>
                <button onClick={copyToClipboard} className="copy-button">
                  Copy
                </button>
              </div>
            </div>
            <div className="legend">
              <span className="legend-item">
                <span className="symbol">·</span> = Space
              </span>
              <span className="legend-item">
                <span className="symbol">→</span> = Tab
              </span>
              <span className="legend-item">
                <span className="symbol">↵</span> = Newline
              </span>
            </div>
            <div className="output-box">
              <pre className="whitespace-output">{output}</pre>
            </div>
          </div>
        )}

        <div className="input-section">
          <h3>Input Text</h3>
          <textarea
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder="Paste your text here..."
            className="whitespace-textarea"
          />
          <div className="button-group">
            <button onClick={showWhitespace} className="show-button">
              Show Whitespace
            </button>
            <button onClick={hideWhitespace} className="hide-button">
              Hide Whitespace
            </button>
            <button onClick={clearAll} className="clear-button">
              Clear All
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default WhitespaceConverter;
